"""GIVEN: load the knowledge base (data/kb, generated by `python -m shopfront.kb`)."""
from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass
from pathlib import Path

from agentlab.config import ROOT

KB = ROOT / "data" / "kb"


@dataclass(frozen=True)
class Doc:
    id: str
    title: str
    type: str          # help | product | guide | troubleshooting | ops
    status: str        # current | archived | discontinued
    updated: str       # YYYY-MM-DD
    text: str          # the markdown body, WITHOUT front matter
    meta: tuple[tuple[str, str], ...] = ()   # any other front-matter fields (sku, category, ...)

    def get(self, key: str, default: str = "") -> str:
        return dict(self.meta).get(key, default)


def parse(text: str, fallback_id: str = "") -> Doc:
    meta: dict[str, str] = {}
    body = text
    if text.startswith("---\n"):
        head, body = text[4:].split("\n---\n", 1)
        meta = dict(re.findall(r"^(\w+): ?(.*)$", head, re.M))
    known = {k: meta.pop(k, "") for k in ("id", "title", "type", "status", "updated")}
    return Doc(known["id"] or fallback_id, known["title"], known["type"], known["status"] or "current",
               known["updated"], body.strip() + "\n", tuple(sorted(meta.items())))


def load_corpus(root: Path = KB) -> list[Doc]:
    docs = [parse(p.read_text(), p.stem) for p in sorted(Path(root).glob("*.md"))]
    if not docs:
        raise FileNotFoundError(f"no documents in {root}: run `python -m shopfront.kb`")
    ids = [d.id for d in docs]
    if len(set(ids)) != len(ids):
        raise ValueError("duplicate document ids in the knowledge base")
    return docs


def corpus_hash(docs: list[Doc]) -> str:
    """Changes whenever any document changes: index caches key on it."""
    h = hashlib.sha256()
    for d in sorted(docs, key=lambda d: d.id):
        # everything that can reach an index row: id, title (chunk headers), status (filters), text
        h.update("\0".join((d.id, d.title, d.status, d.text)).encode() + b"\0\0")
    return h.hexdigest()[:16]
